function neighborsOf(cell: Cell): Cell[] {
  const [x, y] = cell;
  const offsets = [-1, 0, 1];
  return offsets
    .flatMap((dx) => offsets.map((dy): Cell => [x + dx, y + dy]))
    .filter((candidate) => !isSameCell(cell, candidate));
}
